from scipy.optimize import least_squares
L=np.log(1+eps)**2
one=np.ones_like(eps)
sq=np.sqrt(T)
def fit(fn,p0s):
    def resid(p):
        X=np.column_stack([sq,L,one,fn(p)])
        c=np.linalg.lstsq(X,sigma,rcond=None)[0]
        return sigma-X@c
    best=None
    for s in p0s:
        try:
            r=least_squares(resid,s)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    return round(np.mean(best.fun**2)/np.var(sigma),9), np.round(best.x,4)
